      }`}
      style={{ touchAction: 'manipulation' }}
      title={canManage ? uiText("docs — 꾹 누르거나 우클릭하면 가져오기/내보내기") : 'docs'}
    >
      <span className="flex h-5 w-5 items-center justify-center">
        <ProjectIcon icon={DOCS_ICON} size={17} />
      </span>
    </button>
  )
